return ['domain'=>'zinn-chat','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'hr','project-id-version'=>'zinn-chat','pot-creation-date'=>'2026-10-02T02:20:47+00:00','po-revision-date'=>'2026-10-02T02:20:47+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Chat'=>'Zinn® Chat','https://zinndigital.com/wordpress-plugins/zinn-chat'=>'https://zinndigital.com/wordpress-plugins/zinn-chat','A complete help desk and AI assistant that runs on your own WordPress: an AI that answers from your own pages with links, live chat, and support tickets in wp-admin, on a submit-a-ticket page and in the WooCommerce account area. Under 10 KB on the page and no requests at all until a visitor opens it.'=>'Potpuna služba za podršku i AI pomoćnik koji radi na vašem vlastitom WordPress: AI koji odgovara s vaših vlastitih stranica s poveznicama, chatom uživo i tiketima za podršku u wp-adminu, na stranici za podnošenje tiketa i u WooCommerce korisničkom području. Manje od 10 KB na stranici i bez ikakvih zahtjeva dok posjetitelj ne otvori.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Inbox'=>'Prezime','Tickets'=>'Zahtjevi','Assistant'=>'Pomoćnik','Settings'=>'Postavke','Setup'=>'Postavljanje','Zinn® Chat could not create its database tables:'=>'Zinn® Chat nije mogao stvoriti svoje tablice baze podataka:','The AI assistant could not answer a visitor:'=>'AI asistent nije mogao odgovoriti posjetitelju:','Fix it'=>'Popravi to','Loading…'=>'Učitavanje…','This screen needs JavaScript.'=>'Za ovaj je zaslon potreban JavaScript.','Chat'=>'Chat','AI assistant'=>'AI pomoćnik','Tickets and email'=>'Zahtjevi i e-pošta','Site index'=>'Indeks stranice','Privacy and spam'=>'Privatnost i neželjena pošta','Connect to Zinn Digital®'=>'Povežite se s Zinn Digital®','AI agents (MCP)'=>'AI agenti (MCP)','Show the chat on the site'=>'Prikaži chat na stranici','Nothing appears on the site, and nothing is loaded, until this is ticked.'=>'Ništa se ne prikazuje na web-mjestu i ništa se ne učitava dok se ovo ne označi.','Chat title'=>'Naslov chata','Greeting'=>'Pozdrav','The first thing a visitor sees.'=>'Prva stvar koju posjetitelj vidi.','Greeting when nobody can answer'=>'Pozdrav kada nitko ne može odgovoriti','Colour'=>'Boja','Text colour on the colour'=>'Boja teksta na boji','Position'=>'Položaj','Bottom, end side (right in left-to-right languages)'=>'Donji, završni dio (desno u jezicima koji se pišu s lijeva na desno)','Bottom, start side'=>'Donji, početni rub','Offer "Talk to a person"'=>'Ponuda "Razgovarajte s osobom"','Shown while somebody has the Inbox open and is not set to away.'=>'Prikazuje se dok netko ima otvorenu Pristiglu poštu i nije postavljen na odsutan.','Hide the chat from your support team while they are signed in'=>'Sakrijte chat od svog tima za podršku dok su prijavljeni','Show "Powered by Zinn® Chat" under the chat'=>'Prikaži "Powered by Zinn® Chat" ispod chata','Optional. Off unless you turn it on.'=>'Neobavezno. Isključeno ako ga ne uključite.','Let the AI assistant answer visitors'=>'Neka AI pomoćnik odgovara posjetiteljima','Assistant name'=>'Naziv pomoćnika','Extra instructions for the assistant'=>'Dodatne upute za asistenta','For example: "Always mention our 30-day returns." They cannot override the safety rules.'=>'Na primjer: "Uvijek spomenite naše povrate u roku od 30 dana." Oni ne mogu nadjačati sigurnosna pravila.','Answer language'=>'Jezik odgovora','"auto" answers in the visitor\'s own language; or a locale such as en_GB or de_DE to always answer in one language.'=>'"auto" odgovara na jeziku posjetitelja; ili odaberite lokalnu postavku poput en_GB ili de_DE kako biste uvijek odgovarali na jednom jeziku.','Minimum relevance'=>'Minimalna važnost','Passages scoring below this (0 to 0.95) are not used, and the assistant says it does not know. Check scores in the test console.'=>'Odlomci s rezultatom ispod ovoga (0 do 0,95) se ne koriste, a asistent navodi da ne zna. Provjerite rezultate u testnoj konzoli.','Offer a person after this many unanswered questions'=>'Ponudi osobi nakon ovoliko neodgovorenih pitanja','Longest answer (tokens)'=>'Najduži odgovor (tokeni)','Accept support tickets'=>'Prihvaćanje zahtjeva za podršku','Support page'=>'Stranica za podršku','The page with the [zinn_chat_support] shortcode or the Support page block. Ticket links in emails open this page.'=>'Stranica s kratkim kodom [zinn_chat_support] ili blokom Stranice podrške. Veze na tikete u e-porukama otvaraju ovu stranicu.','Send team alerts to'=>'Šalji timska upozorenja na','One or more email addresses, separated by commas. Empty: the site admin email.'=>'Jedna ili više adresa e-pošte odvojenih zarezima. Prazno: adresa e-pošte administratora web-mjesta.','Sender name on emails'=>'Naziv pošiljatelja u e-porukama','Email the team when a visitor waits for a person longer than (minutes)'=>'Pošaljite e-poruku timu kada posjetitelj čeka osobu dulje od (minuta)','Private ticket links work for (days after the last message)'=>'Privatne poveznice na tikete vrijede (dana nakon posljednje poruke)','After that the page offers to email a new link.'=>'Nakon toga stranica nudi slanje nove poveznice e-poštom.','Add a Support tab to the WooCommerce account area'=>'Dodajte karticu Podrška u područje korisničkog računa za WooCommerce','Let the assistant tell signed-in customers about their own orders'=>'Dopustite pomoćniku da obavijesti prijavljene kupce o njihovim narudžbama','Answers "where is my order?" from the order status and tracking.'=>'Odgovara na pitanje „gdje je moja narudžba?“ na temelju statusa narudžbe i praćenja.','Content the assistant reads'=>'Sadržaj koji pomoćnik čita','None ticked means every public type.'=>'Nije označeno nijedno znači svaka javna vrsta.','WooCommerce products, prices, stock, shipping and payment methods'=>'WooCommerce proizvodi, cijene, zalihe, načini dostave i plaćanja','Forums (bbPress, BuddyBoss, wpForo)'=>'Forumi (bbPress, BuddyBoss, wpForo)','Read pages as visitors see them when a page builder\'s content cannot be read directly'=>'Čitajte stranice onako kako ih vide posjetitelji kada se sadržaj graditelja stranica ne može izravno pročitati','Fetches the page from your own site in the background.'=>'Dohvaća stranicu s vaše vlastite stranice u pozadini.','Never read these posts or pages (IDs)'=>'Nikada ne čitaj ove objave ili stranice (ID-ovi)','Comma-separated.'=>'Odvojeno zarezima.','Ask visitors to agree before a chat or ticket'=>'Zatražite od posjetitelja pristanak prije chata ili tiketa','Agreement text'=>'Tekst ugovora','Privacy policy link'=>'Poveznica na pravila o privatnosti','Empty: the site\'s privacy policy page.'=>'Prazno: stranica s pravilima o privatnosti web-mjesta.','Delete finished chats and tickets after (days)'=>'Izbriši završene razgovore i tikete nakon (dana)','0 keeps them.'=>'0 ih čuva.','Store visitors\' IP addresses'=>'Spremi IP adrese posjetitelja','Off: only a coded form is kept, enough for spam limits.'=>'Isključeno: pohranjuje se samo kodirani oblik, dovoljan za ograničenja neželjene pošte.','Messages per visitor per hour'=>'Poruke po posjetitelju po satu','Chats per visitor per day'=>'Razgovori po posjetitelju dnevno','Tickets per visitor per day'=>'Ulaznica po posjetitelju po danu','Longest chat message (characters)'=>'Najduža poruka u chatu (znakovi)','Block list'=>'Popis blokiranih','One per line: an IP address, an email address, @domain.com, or a word.'=>'Jedno po retku: IP adresa, adresa e-pošte, @domain.com ili riječ.','Where chats are answered'=>'Gdje se odgovara na razgovore','"This site" keeps everything in this site\'s database and uses your own AI key. "Zinn Digital®" uses the hosted inbox in the Zinn® app (for Zinn® hosting customers).'=>'"This site" sprema sve u bazu podataka ove stranice i koristi vaš vlastiti AI ključ. "Zinn Digital®" koristi hostirani pretinac u aplikaciji Zinn® (za korisnike Zinn® hostinga).','This site (recommended)'=>'Ovo web-mjesto (preporučeno)','Zinn Digital® app'=>'Zinn Digital® aplikacija','Zinn® widget key'=>'ključ widgeta za Zinn®','From the Zinn® app: Live chat, then your widget. Starts with zc_.'=>'Iz aplikacije Zinn®: Live chat, zatim vaš widget. Počinje sa zc_.','Allow AI agents (MCP)'=>'Dopusti AI agentima (MCP)','Off: the tools below and their REST routes are not registered at all.'=>'Isključeno: alati u nastavku i njihove REST rute uopće nisu registrirani.','Zinn® Chat settings'=>'Postavke za Zinn® Chat','Settings saved.'=>'Postavke su spremljene.','The assistant uses your own AI key.'=>'Pomoćnik koristi vaš vlastiti AI ključ.','AI providers and models'=>'AI davatelji i modeli','— None —'=>'— Nijedno —','Saved — leave empty to keep'=>'Spremljeno — ostavite prazno za zadržavanje postojećeg','Remove the saved key'=>'Ukloni spremljeni ključ','You are not allowed to change these settings.'=>'Nije vam dopušteno mijenjati ove postavke.','Turn the chat on'=>'Uključi chat','The chat is showing on your site.'=>'Chat se prikazuje na vašoj stranici.','Nothing is shown or loaded on your site until you turn it on.'=>'Ništa se ne prikazuje niti učitava na vašoj web-lokaciji dok to ne uključite.','Turn off'=>'Isključi','Turn on'=>'Uključi','Connect your AI provider'=>'Povežite svog AI pružatelja usluga','Connected. Site search uses %1$s (%2$s).'=>'Povezano. Pretraživanje web-mjesta koristi %1$s (%2$s).','Connected. Your provider cannot build a meaning-based index, so the assistant uses keyword search. Add a Google Gemini, OpenAI, Mistral or OpenRouter key for better answers.'=>'Povezano. Vaš pružatelj usluga ne može izgraditi indeks temeljiljen na značenju, pa pomoćnik koristi pretraživanje po ključnim riječima. Dodajte ključ za Google Gemini, OpenAI, Mistral ili OpenRouter za bolje odgovore.','Add a key for Google Gemini, OpenAI, Anthropic Claude, Mistral, OpenRouter or any OpenAI-compatible service. The newest model is chosen for you; you can change it.'=>'Dodajte ključ za Google Gemini, OpenAI, Anthropic Claude, Mistral, OpenRouter ili bilo koju uslugu kompatibilnu s OpenAI-jem. Najnoviji model bit će odabran za vas; možete ga promijeniti.','AI providers'=>'AI pružatelji usluga','Let the assistant read your site'=>'Dopustite pomoćniku da pročita vašu web-lokaciju','%1$d pages read, %2$d waiting, %3$d passages. New and edited content is picked up automatically.'=>'%1$d pročitano stranica, %2$d na čekanju, %3$d ulaza. Novi i uređeni sadržaj preuzima se automatski.','Read the whole site now'=>'Pročitajte cijelu web-lokaciju sada','Create your support page'=>'Izradite svoju stranicu podrške','Visitors submit tickets there, and ticket emails link to it.'=>'Posjetitelji ondje šalju zahtjeve, a e-poruke sa zahtjevima vode do toga.','A page with the ticket form, where customers also follow their requests.'=>'Stranica s obrascem za tiket, na kojoj korisnici također prate svoje zahtjeve.','View'=>'Pregledaj','Create the support page'=>'Izradi stranicu za podršku','Add "Submit a ticket" and "Chat with us" to a menu'=>'Dodajte "Pošaljite zahtjev" i "Razgovarajte s nama" u izbornik','Appearance, Menus: use the Zinn® Chat box. Or add the Zinn® Chat blocks to any page, in any page builder.'=>'Izgled, Izbornici: upotrijebite okvir Zinn® Chat. Ili dodajte blokove Zinn® Chat na bilo koju stranicu, u bilo kojem generatoru stranica.','Menus'=>'Izbornici','WooCommerce account area'=>'Područje računa za WooCommerce','Customers see their tickets under Support in My Account, and the assistant can tell them where their order is.'=>'Korisnici vide svoje tikete pod Podrškom u Mojem računu, a asistent im može reći gdje se nalazi njihova narudžba.','Test the assistant'=>'Testiraj pomoćnika','Ask it questions and see exactly which pages it answered from, including out-of-date ones.'=>'Postavljajte joj pitanja i točno vidite s kojih je stranica odgovorila, uključujući i zastarjele.','Open the test console'=>'Otvorite testnu konzolu','Answer live chats'=>'Odgovaraj na razgovore uživo','Visitors can ask for a person while you have the Inbox open. It works on a phone too.'=>'Posjetitelji mogu zatražiti razgovor s osobom dok vam je pretinac pristigle pošte otvoren. Radi i na telefonu.','Open the Inbox'=>'Otvorite pretinac','Set up Zinn® Chat'=>'Postavite Zinn® Chat','This site is connected to the Zinn Digital® app: chats are answered there. To run the help desk on this site instead, choose "This site" under Settings, Connect to Zinn Digital®.'=>'Ova je stranica povezana s aplikacijom Zinn Digital®: razgovori se odgovaraju tamo. Kako biste umjesto toga pokrenuli službu za podršku na ovoj stranici, odaberite "Ova stranica" pod Postavke, Poveži se s Zinn Digital®.','You are not allowed to do that.'=>'Nije vam dopušteno to učiniti.','Unlimited agents, with a Support agent role that sees only chats and tickets'=>'Neograničen broj agenata, s ulogom agenta za podršku koji vidi samo razgovore i tikete','Reply to tickets by email'=>'Odgovorite na tikete putem e-pošte','Knowledge base: articles, categories, search, and a KB section in the chat'=>'Baza znanja: članci, kategorije, pretraživanje i KB odjeljak u chatu','Saved replies, business hours, priorities and SLAs'=>'Spremljeni odgovori, radno vrijeme, prioriteti i SLA-ovi','Suggested replies, thread summaries and auto-tagging by AI'=>'Predloženi odgovori, sažeci nitâ i automatsko označavanje pomoću umjetne inteligencije','Knowledge-gap report: the questions your site could not answer'=>'Izvješće o prazninama u znanju: pitanja na koja vaša stranica nije mogla odgovoriti','Push notifications and an installable agent app for your phone'=>'Push obavijesti i aplikacija agenta koja se može instalirati na vaš telefon','Proactive messages, reports, webhooks, Slack and Telegram alerts'=>'Proaktivne poruke, izvješća, webhooks, Slack i Telegram upozorenja','Zinn® Chat Pro'=>'Zinn® Chat Pro','From $%1$d a month or $%2$d a year for one site.'=>'Od $%1$d mjesečno ili $%2$d godišnje za jednu stranicu.','Try Pro free for 14 days'=>'Isprobajte Pro besplatno 14 dana','See plans'=>'Pogledajte planove','No card needed for the trial.'=>'Za probno razdoblje nije potrebna kartica.','The makers of ChatGPT. A good all-rounder.'=>'Tvorci modela ChatGPT. Dobar svestrani alat.','The makers of Claude. Strong at writing and careful reasoning.'=>'Tvorci sustava Claude. Snažni u pisanju i opreznom zaključivanju.','Google\'s Gemini models. Fast and inexpensive.'=>'Googleovi modeli Gemini. Brzi i povoljni.','A European AI company with fast, inexpensive models.'=>'Europska AI tvrtka s brzim i povoljnim modelima.','Low-cost models that are good at writing and code.'=>'Jeftini modeli koji su dobri u pisanju i pisanju koda.','One key for models from many different providers.'=>'Jedan ključ za modele od mnogo različitih pružatelja usluga.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'Bilo koja usluga koja radi poput OpenAI-jevog API-ja, uključujući model koji se izvodi na vašem vlastitom računalu ili poslužitelju.','General (used when nothing more specific is set)'=>'Općenito (koristi se kada ništa specifičnije nije postavljeno)','Writing and rewriting'=>'Pisanje i prepisivanje','Translation'=>'Prijevod','Code and CSS'=>'Kod i CSS','Sorry, you are not allowed to access this page.'=>'Žao nam je, nemate dopuštenje za pristup ovoj stranici.','These settings are shared by every plugin that uses them: %s.'=>'Ove postavke dijele svi dodaci koji ih koriste: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'Vaši su ključevi šifrirani u bazi podataka ove web-lokacije i šalju se samo davatelju usluga kojeg ste odabrali – nikada nama.','Step 1 of 2: choose an AI provider'=>'1. korak od 2: odaberite AI pružatelja usluga','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'Donosite vlastiti ključ, tako da pružatelju usluga plaćate izravno za ono što koristite. Niste sigurni? Bilo koja od ovih opcija dobro funkcionira; kasnije možete dodati još.','Next'=>'Sljedeće','Step 2 of 2: connect %s'=>'2. korak od 2: povežite %s','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'Unesite adresu svoje usluge kompatibilne s OpenAI koja završava s /v1. Ključ je potreban samo ako ga usluga zatraži.','Open %s and sign in (or create a free account).'=>'Otvorite %s i prijavite se (ili izradite besplatan račun).','the %s API keys page'=>'stranica za API ključeve %s','Create a new key and copy it.'=>'Stvorite novi ključ i kopirajte ga.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'Zalijepite ga ispod i pritisnite "Spremi i testiraj". Šaljemo jedan mali zahtjev kako bismo provjerili radi li.','Most providers need a little credit on the account before a key works: %s.'=>'Većini pružatelja usluga potreban je mali iznos na računu prije nego što ključ počne raditi: %s.','add credit'=>'dodaj kredit','← Choose a different provider'=>'← Odaberi drugog pružatelja usluga','Address'=>'Adresa','Saved key ends in …%s — paste a new one to replace it'=>'Spremljeni ključ završava s …%s — zalijepite novi da biste ga zamijenili','Key (optional)'=>'Ključ (izborno)','API key'=>'API ključ','Save and test'=>'Spremi i testiraj','Providers'=>'Davatelji','Provider'=>'Pružatelj usluga','Status'=>'Status','Key'=>'Ključni','Get a key'=>'Dohvati ključ','Test'=>'Test','Remove'=>'Ukloni','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'Spremljeno novijom verzijom dodatka: ažurirajte ovaj dodatak ili ponovno unesite ključ.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'Spremljeni ključ se više ne može otvoriti (sigurnosni ključevi web-mjesta su promijenjeni). Unesite ga ponovno.','Not connected'=>'Nije povezano','Connected — last test passed %s'=>'Povezano — posljednji test je prošao %s','Last test failed: %s'=>'Posljednji test nije uspio: %s','Connected — not tested yet'=>'Povezano — još nije testirano','Which model to use'=>'Koji model koristiti','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ označava našu preporuku za taj zadatak. Popis uključuje svaki model koji vaš ključ može koristiti, učitan uživo od davatelja usluge.','— Recommended for the provider —'=>'— Preporučeno za davatelja —','Save models'=>'Spremi modele','Refresh the model lists from the providers'=>'Osvježite popise modela od davatelja usluga','Images'=>'Slike','Connect OpenAI or Google Gemini to make images.'=>'Povežite OpenAI ili Google Gemini za izradu slika.','— The newest image model of the first connected provider —'=>'— Najnoviji model slike prvog povezanog davatelja usluge —','Site search (embeddings)'=>'Pretraživanje web-mjesta (ugrađivanja)','Connect Google Gemini, OpenAI, Mistral or OpenRouter to build a search index of your site.'=>'Povežite Google Gemini, OpenAI, Mistral ili OpenRouter kako biste izgradili indeks pretraživanja svoje web-lokacije.','— The newest embedding model of the first connected provider —'=>'— Najnoviji model ugrađivanja prvog povezanog pružatelja usluga —','Changing this rebuilds the search index of every plugin that uses it.'=>'Promjena ovoga ponovno izrađuje indeks pretraživanja svakog dodatka koji ga koristi.','best quality'=>'najbolja kvaliteta','lowest cost'=>'najniža cijena','fastest'=>'najbrže','Add a model yourself'=>'Dodajte model sami','A model came out today? Paste its exact name to use it straight away.'=>'Danas je izašao novi model? Zalijepite njegov točan naziv kako biste ga odmah počeli koristiti.','Model name'=>'Naziv modela','Add model'=>'Dodaj model','Recommended models list'=>'Popis preporučenih modela','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'Popis preporučenih modela nije mogao biti potvrđen, stoga se preporuke ne prikazuju. Ponovno instalirajte dodatak ili uključite dnevna ažuriranja u nastavku.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'Korišteni popis objavljen je %s. Svako ažuriranje dodatka donosi novi.','Also check Zinn Digital® once a day for an updated list.'=>'Također provjerite Zinn Digital® jednom dnevno za ažurirani popis.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Šalje se samo običan zahtjev za preuzimanje: bez ključa, bez adrese web-mjesta, ništa o vašem sadržaju. Popis je potpisan, a popis koji ne prođe provjeru potpisa se zanemaruje.','Last checked %1$s: %2$s.'=>'Posljednja provjera %1$s: %2$s.','Save, and check now if turned on'=>'Spremite i provjerite odmah ako je uključeno','a newer list was installed'=>'noviji popis je instaliran','already up to date'=>'već ažurirano','the download failed the signature check and was ignored'=>'preuzimanje nije prošlo provjeru potpisa i zanemareno je','Zinn Digital® could not be reached; the current list stays in use'=>'Zinn Digital® nije dostupan; trenutačni popis ostaje u upotrebi','turned off'=>'isključeno','Open'=>'Otvori','Check their status page'=>'Provjerite njihovu stranicu sa statusom','Open your billing page'=>'Otvorite svoju stranicu za naplatu','Open your API keys page'=>'Otvorite stranicu sa svojim API ključevima','Open the AI settings'=>'Otvorite AI postavke','Sorry, you are not allowed to do that.'=>'Žao nam je, nemate dopuštenje za to.','Unknown provider.'=>'Nepoznati davatelj usluga.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Unesite adresu svoje usluge, na primjer http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'To ne izgleda kao API ključ. Kopirajte ga ponovno, bez razmaka.','Paste your API key first.'=>'Prvo zalijepite svoj API ključ.','Key removed.'=>'Ključ je uklonjen.','Models saved.'=>'Modeli su spremljeni.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'Unesite točan naziv modela, na primjer kako je naveden u dokumentaciji davatelja usluge.','Added %s. Choose it under "Which model to use".'=>'Dodano %s. Odaberite ga pod "Koji model koristiti".','Model removed.'=>'Model je uklonjen.','Daily updates are off. The list that came with the plugin is used.'=>'Dnevna ažuriranja su isključena. Koristi se popis koji je došao s dodacima.','Checked: %s.'=>'Označeno: %s.','Model lists refreshed.'=>'Popisi modela su osvježeni.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'Vaš AI ključ spremila je novija verzija jednog od vaših dodataka. Ažurirajte ovaj dodatak ili ponovo unesite ključ u postavkama za AI.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'Vaš spremljeni AI ključ se više ne može otvoriti (sigurnosni ključevi web-mjesta su promijenjeni). Unesite ga ponovno u AI postavkama.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'AI još nije postavljen. Dodajte ključ za AI pružatelja usluga u AI postavkama.','No model is chosen for this task. Pick one in the AI settings.'=>'Za ovaj zadatak nije odabran nijedan model. Odaberite jedan u postavkama umjetne inteligencije.','That AI provider is not supported by this version of the plugin.'=>'Taj pružatelj usluga umjetne inteligencije nije podržan od strane ove verzije dodatka.','No AI provider that can make images is connected. Add an OpenAI or Google Gemini key in the AI settings.'=>'Nije povezan nijedan pružatelj usluge umjetne inteligencije koji može izrađivati slike. Dodajte ključ za OpenAI ili Google Gemini u postavkama umjetne inteligencije.','This AI provider cannot make images. Choose OpenAI or Google Gemini for images in the AI settings.'=>'Ovaj pružatelj usluge umjetne inteligencije ne može stvarati slike. Odaberite OpenAI ili Google Gemini za slike u postavkama umjetne inteligencije.','Your AI key cannot use any image model. Check the key\'s permissions with the provider, or choose another provider for images.'=>'Vaš AI ključ ne može koristiti nijedan model slike. Provjerite dopuštenja ključa kod davatelja usluge ili odaberite drugog davatelja usluge za slike.','No connected AI provider can build a search index. Add a Google Gemini, OpenAI, Mistral or OpenRouter key in the AI settings.'=>'Nijedan povezani pružatelj usluge umjetne inteligencije ne može izgraditi indeks pretraživanja. Dodajte ključ za Google Gemini, OpenAI, Mistral ili OpenRouter u postavkama umjetne inteligencije.','Your AI key cannot use any embedding model. Check the key\'s permissions with the provider, or choose another provider for site search.'=>'Vaš AI ključ ne može koristiti nijedan model ugradnje. Provjerite dozvole ključa kod davatelja usluge ili odaberite drugog davatelja usluge za pretraživanje web-mjesta.','This AI provider cannot build a search index. Connect Google Gemini, OpenAI, Mistral or a compatible service for site search.'=>'Ovaj pružatelj usluga umjetne inteligencije ne može izgraditi indeks pretraživanja. Povežite Google Gemini, OpenAI, Mistral ili kompatibilnu uslugu za pretraživanje web-mjesta.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Ova stranica ne može dosegnuti vašu AI uslugu. Provjerite radi li i je li njena adresa dostupna s vašeg web-poslužitelja (usluga na vašem vlastitom računalu nije dostupna s hostirane stranice).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Ova stranica nije mogla dosegnuti %s. Provjerite njihovu stranicu statusa; ako rade, vaš poslužitelj možda blokira odlazne veze ili je adresa pogrešna.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s navodi da vaš račun više nema sredstava ni kvote. Dodajte sredstva ili povećajte ograničenje na svom računu kod njih, a zatim pokušajte ponovno.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s nije prihvatio vaš ključ. Možda je pogrešno upisan, opozvan ili je istekao. Izradite novi ključ i zalijepite ga ovdje.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s je odbio ovaj zahtjev za vaš ključ. Ključ možda nema pristup ovom modelu ili značajci, ili je vaš račun potrebno verificirati.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'Model "%1$s" nije dostupan od davatelja %2$s za vaš ključ. Odaberite drugi model u AI postavkama.','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'Vaš paket %2$s ne uključuje model "%1$s". Odaberite drugi model u AI postavkama ili nadogradite svoj paket.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s ograničava brzinu kojom vaš ključ može slati zahtjeve. Pričekajte minutu i pokušajte ponovno ili povećajte ograničenje brzine kod njih.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s trenutačno ima problema (prekid rada ili preopterećenje na njihovoj strani). Vaše postavke su ispravne. Pokušajte ponovno uskoro.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'Zahtjev prema umjetnoj inteligenciji nije uspio iz nepoznatog razloga. Pokušajte ponovno; ako se to nastavi događati, obratite se podršci s dolje navedenim detaljima.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'Pružatelj usluga umjetne inteligencije odgovorio je u obliku koji ovaj dodatak nije mogao pročitati. Pokušajte ponovno; ako se to nastavi događati, odaberite drugi model ili se obratite podršci.','Custom (OpenAI-compatible)'=>'Prilagođeno (kompatibilno s OpenAI)','Save a key for this provider first.'=>'Prvo spremite ključ za ovog pružatelja usluga.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'Vaš ključ radi, ali pružatelj usluge za njega ne navodi ni jedan tekstualni model. U nastavku sami dodajte model.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'Povezano. %1$s se javio koristeći %2$s. Vaše AI značajke spremne su za korištenje.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Vaša korisnička uloga nema dopuštenje za korištenje umjetne inteligencije na ovoj web-lokaciji. Obratite se administratoru.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Ova je stranica dosegnula mjesečni limit potrošnje za AI. Administrator ga može povećati u postavkama za AI.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Ova je stranica dosegnula mjesečni limit AI zahtjeva. Administrator ga može povećati u postavkama za AI.','Usage and cost'=>'Korištenje i troškovi','The log, limits and role permissions apply to AI used through: %s.'=>'Dnevnik, ograničenja i dopuštenja uloga primjenjuju se na AI koji se koristi putem: %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'Troškovi su približni, izračunati na temelju objavljenih cijena; model bez poznate cijene računa se kao nula.','This month: %1$s requests, about %2$s.'=>'Ovog mjeseca: %1$s zahtjeva, oko %2$s.','When'=>'Kada','Who'=>'Tko','Used for'=>'Koristi se za','Model'=>'Model','Tokens in / out'=>'Tokeni / izlazni tokeni','About'=>'O programu','Result'=>'Rezultat','No AI requests have been made yet.'=>'Još nije podnesen nijedan zahtjev za AI.','Done'=>'Gotovo','Limits and permissions'=>'Ograničenja i dozvole','Monthly spending limit (US dollars)'=>'Mjesečni limit potrošnje (US dolara)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'Ostavite prazno za bez ograničenja. AI se zaustavlja do kraja mjeseca kada procijenjeni trošak dosegne tu vrijednost.','Monthly request limit'=>'Mjesečno ograničenje zahtjeva','Leave empty for no limit.'=>'Ostavite prazno za bez ograničenja.','Who may use AI'=>'Tko može koristiti AI','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'Označite ništa kako biste omogućili svima koji mogu koristiti značajke dodatka da koriste umjetnu inteligenciju. Administratori je uvijek mogu koristiti.','Save limits and permissions'=>'Spremi ograničenja i dozvole','Limits and permissions saved.'=>'Ograničenja i dozvole su spremljeni.','Content'=>'Sadržaj','Not found.'=>'Nije pronađeno.','%s joined the chat.'=>'%s se pridružio/la razgovoru.','Type a reply first.'=>'Prvo upišite odgovor.','The chat has ended. Thank you for contacting us.'=>'Razgovor je završen. Hvala vam što ste nas kontaktirali.','You are chatting with the assistant again.'=>'Ponovno razgovarate s pomoćnikom.','This conversation is now ticket #%d. We will reply by email.'=>'Ovaj razgovor je sada zahtjev #%d. Odgovorit ćemo putem e-pošte.','Type a question first.'=>'Prvo upišite pitanje.','The whole site is being read again in the background.'=>'Cijela se web-lokacija ponovno učitava u pozadini.','Meanings are being rebuilt in the background.'=>'Značenja se ponovno grade u pozadini.','Submit a ticket form'=>'Pošaljite obrazac za podršku','Heading'=>'Naslov','Default subject'=>'Zadani predložak','Button text'=>'Tekst gumba','Show the subject field (yes or no)'=>'Prikaži polje predmeta (da ili ne)','My support requests'=>'Moji zahtjevi za podršku','Chat button'=>'Gumb za chat','Chat with us'=>'Razgovarajte s nama','Support'=>'Podrška','Thank you. Your request is ticket #%d. We have emailed you a link to follow it.'=>'Hvala vam. Vaš zahtjev je tiket #%d. Poslali smo vam e-poruku s poveznicom za praćenje.','Your reply has been sent.'=>'Vaš odgovor je poslan.','If there is a request under that address, we have emailed you a new link.'=>'Ako postoji zahtjev na toj adresi, poslali smo vam novu vezu e-poštom.','Something went wrong. Please check the form and try again.'=>'Nešto je pošlo po zlu. Provjerite obrazac i pokušajte ponovno.','Your message could not be sent.'=>'Vašu poruku nije bilo moguće poslati.','You are sending messages too quickly. Please wait a little and try again.'=>'Prebrzo šaljete poruke. Molimo pričekajte malo i pokušajte ponovno.','Please agree to the privacy notice to send your request.'=>'Molimo prihvatite obavijest o privatnosti kako biste poslali svoj zahtjev.','Please complete the check to show you are not a robot.'=>'Molimo dovršite provjeru kako biste dokazali da niste robot.','Sign in to see your support requests.'=>'Prijavite se kako biste vidjeli svoje zahtjeve za podršku.','Your name'=>'Vaše ime','Your email'=>'Vaša e-pošta','Subject'=>'Predmet','Which order is this about?'=>'O kojoj se narudžbi radi?','Not about an order'=>'Nije vezano uz narudžbu','How can we help?'=>'Kako vam možemo pomoći?','Privacy policy'=>'Pravila o privatnosti','Send request'=>'Pošalji zahtjev','All requests'=>'Svi zahtjevi','Your support requests'=>'Vaši zahtjevi za podršku','You have no support requests yet.'=>'Nemate još nijedan zahtjev za podršku.','Updated'=>'Ažurirano','New request'=>'Novi zahtjev','This link has expired. Enter your email address and we will send you a new one.'=>'Ova je poveznica istekla. Unesite svoju adresu e-pošte i poslat ćemo vam novu.','This link is not valid. Enter your email address and we will send you a link to your requests.'=>'Ova veza nije važeća. Unesite svoju adresu e-pošte i poslat ćemo vam poveznicu na vaše zahtjeve.','Email me a new link'=>'Pošaljite mi novu vezu e-poštom','Request #%1$d: %2$s'=>'Zahtjev #%1$d: %2$s','Status:'=>'Status:','Your reply'=>'Vaš odgovor','Send reply'=>'Pošalji odgovor','You'=>'Vi','Submit a ticket'=>'Pošalji zahtjev','Add to Menu'=>'Dodaj u izbornik','Create the support page on the Zinn® Chat setup screen to add a "Submit a ticket" link.'=>'Stvorite stranicu podrške na zaslonu za postavljanje Zinn® Chat kako biste dodali vezu „Pošalji zahtjev”.','[#%1$d] We have your request: %2$s'=>'[#%1$d] Primili smo vaš zahtjev: %2$s','Thank you for contacting us. We have received your request and will reply as soon as we can.'=>'Hvala vam što ste nas kontaktirali. Primili ste naš zahtjev i odgovorit ćemo vam čim prije bude moguće.','View your request'=>'Pregledaj svoj zahtjev','[#%1$d] New ticket: %2$s'=>'[#%1$d] Novi zahtjev: %2$s','Open the ticket'=>'Otvorite tiket','[#%1$d] New reply: %2$s'=>'[#%1$d] Novi odgovor: %2$s','You can reply on the page below.'=>'Možete odgovoriti na stranici ispod.','View and reply'=>'Pogledaj i odgovori','[#%1$d] Customer replied: %2$s'=>'[#%1$d] Korisnik je odgovorio: %2$s','A visitor is waiting in chat #%d'=>'Posjetitelj čeka u chatu #%d','A visitor asked to talk to a person and is waiting for an answer.'=>'Posjetitelj je zatražio razgovor s osobom i čeka odgovor.','Answer now'=>'Odgovori odmah','Your chat with %s'=>'Vaš razgovor s korisnikom %s','[#%d] Your link to your request'=>'[#%d] Vaša veza na vaš zahtjev','Here is a new link to your request. The old one no longer works.'=>'Evo nove veze za vaš zahtjev. Stara više ne radi.','From: %s'=>'Od: %s','a visitor'=>'posjetitelj','Zinn® Chat chats and support tickets'=>'Razgovori i tiketi za podršku za Zinn® Chat','Chats'=>'Razgovori','Started'=>'Pokrenuto','Name'=>'Naziv','Email'=>'E-pošta','Page'=>'Stranica','Messages'=>'Poruke','Support tickets'=>'Korisnički zahtjevi','Ticket'=>'Zahtjev za podršku','Opened'=>'Otvoreno','When you use the chat or submit a support request, we store your messages, the name and email address you give us, the page you were on and a coded form of your IP address, so that we can answer you and keep a record of your request.'=>'Kada koristite chat ili pošaljemo zahtjev za podršku, pohranjujemo vaše poruke, ime i adresu e-pošte koje nam date, stranicu na kojoj ste bili i kodirani oblik vaše IP adrese, kako bismo vam mogli odgovoriti i sačuvati evidenciju o vašem zahtjevu.','If our AI assistant answers you, your message and passages from this website are sent to the AI provider we use to produce the answer.'=>'Ako vam naš AI pomoćnik odgovori, vaša poruka i ulomci s ove web-lokacije šalju se pružatelju usluge umjetne inteligencije kojeg koristimo za generiranje odgovora.','This chat has ended.'=>'Ovaj je chat završen.','The chat is not available right now.'=>'Razgovor trenutno nije dostupan.','Please type a message.'=>'Molimo upišite poruku.','Please agree to the privacy notice to start the chat.'=>'Molimo vas da prihvatite obavijest o privatnosti kako biste započeli razgovor.','You have started too many chats today. Please try again tomorrow or send us a ticket.'=>'Započeli ste previše razgovora danas. Molimo pokušajte ponovno sutra ili nam pošaljite zahtjev.','The chat could not be started. Please try again.'=>'Razgovor nije moguće pokrenuti. Molimo pokušajte ponovno.','Nobody can answer in chat right now. Leave your email address and we will reply by email.'=>'Trenutno nitko ne može odgovoriti u chatu. Ostavite svoju adresu e-pošte i odgovorit ćemo vam putem e-pošte.','The assistant cannot answer right now. You can ask for a person or leave us a message.'=>'Pomoćnik trenutno ne može odgovoriti. Možete zatražiti osobu ili nam ostaviti poruku.','We are putting you through to a person. Please stay on this page.'=>'Spajamo vas s osobom. Molimo ostanite na ovoj stranici.','Tickets are not available right now.'=>'Ulaznice trenutno nisu dostupne.','Visitor'=>'Posjetitelj','Team'=>'Tim','Chat so far:'=>'Dosadašnji razgovor:','Thank you. Your request is ticket #%d and we will reply by email.'=>'Hvala vam. Vaš zahtjev je zabilježen pod brojem #%d i odgovorit ćemo vam putem e-pošte.','Please enter a valid email address.'=>'Molimo unesite važeću adresu e-pošte.','This link is not valid.'=>'Ova poveznica nije valjana.','This link has expired. We can email you a new one.'=>'Ova poveznica je istekla. Možemo vam poslati novu e-poštom.','You cannot see this ticket.'=>'Ne možete vidjeti ovaj zahtjev.','Hi! Ask me anything about this site. I answer from its own pages, and I can put you through to a person.'=>'Pozdrav! Pitajte me bilo što o ovoj stranici. Odgovaram na temelju njezinih stranica, a mogu vas spojiti i s osobom.','Hi! How can we help? Send us a message and we will get back to you.'=>'Pozdrav! Kako vam možemo pomoći? Pošaljite nam poruku i javit ćemo vam se.','Nobody is online right now. Leave your question and email address and we will reply by email.'=>'Trenutno nitko nije na mreži. Ostavite svoje pitanje i adresu e-pošte, a mi ćemo vam odgovoriti putem e-pošte.','We keep this conversation so we can answer you.'=>'Čuvamo ovaj razgovor kako bismo vam mogli odgovoriti.','Please enter a valid email address so we can reply.'=>'Unesite valjanu adresu e-pošte kako bismo vam mogli odgovoriti.','Please describe what you need help with.'=>'Molimo vas da opišete s čime trebate pomoć.','The ticket could not be saved. Please try agai